pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata tos, uint v) public {
        vm.assume(tos.length == 1);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(tos[0] != address(0));
        vm.assume(caddress != address(c));
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        vm.mockCall(caddress, abi.encodeWithSelector(id, from, tos[0], v), abi.encode(true));
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool ret) { ok = ret; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? _tos.length > 0 : true);
    }
    receive() external payable {}
}

