    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bool firstReverted;
        try c.transfer(from, caddress, _tos, v) { firstReverted = false; } catch { firstReverted = true; }
        if (!firstReverted) {
