contract InvMutTest {
    C c;
    uint private callCount;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(true);
        callCount = 0;
        bool reverted; try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? callCount > 0 : true);
    }
    receive() external payable {
        callCount++;
    }
}

