pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Ensure caddress is a contract that will return true on an empty fallback.
        // To keep the domain wide, we deploy a minimal mock that always succeeds.
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(this));
        // Ensure we have enough gas and no state conflicts
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // Deploy a helper contract that always returns true on any call
        Mock callee = new Mock();
        caddress = address(callee);

        bool ok = true;
        try c.transfer(from, caddress, _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // For the reference, the call should succeed (not revert) because callee always returns true.
        // The mutant always reverts, so ok will be false.
        assertTrue(ok);
    }
}

contract Mock {
    fallback() external returns (bool) {
        return true;
    }
}

